type Matrix<T> = Vec<Vec<T>>;

fn broadcast(a: Vec<i8>, shape: Vec<u8>) -> Matrix<i8> {
    let r = shape[0] as usize;
    let c = shape[1] as usize;
    let len = a.len();

    // If length matches number of rows, broadcast as column vector
    if len == r {
        // For each row i, replicate a[i] c times
        (0..r)
            .map(|i| vec![a[i]; c])
            .collect()
    }
    // Otherwise, length matches number of columns: broadcast as row vector
    else {
        // For each row, duplicate entire array a
        (0..r)
            .map(|_| a.clone())
            .collect()
    }
}